# The accounts every organization starts with (kept here as data: services.DEFAULT_ACCOUNTS may change).
DEFAULT_ACCOUNTS = (("cash", "Caisse", 10), ("bank", "Banque principale", 20))


def add_default_accounts(apps, schema_editor):
    """A Caisse and a main bank account for every organization (D-219); the office renames them."""
    Organization = apps.get_model("core", "Organization")
    TreasuryAccount = apps.get_model("treasury", "TreasuryAccount")
    for organization in Organization.objects.all():
        for kind, name, position in DEFAULT_ACCOUNTS:
            if not TreasuryAccount.objects.filter(organization=organization, kind=kind, is_default=True).exists():
                TreasuryAccount.objects.create(
                    organization=organization, kind=kind, name=name, is_default=True, position=position
                )


